from enum import Enum

class S(Enum):
    PRE = "pre-activation"
    ACTIVE = "active"
    DEACTIVATED = "deactivated"
    COMPROMISED = "compromised"
    DESTROYED = "destroyed"

ALLOWED = {
    S.PRE: {S.ACTIVE, S.DESTROYED, S.COMPROMISED},
    S.ACTIVE: {S.DEACTIVATED, S.COMPROMISED},
    S.DEACTIVATED: {S.DESTROYED, S.COMPROMISED},
    S.COMPROMISED: {S.DESTROYED},
    S.DESTROYED: set(),
}

class Slot:
    def __init__(self, kid):
        self.kid, self.state, self.key = kid, S.PRE, bytearray(b"\xaa" * 32)

    def move(self, to):
        if to not in ALLOWED[self.state]:
            raise ValueError(f"{self.kid}: {self.state.value} -> {to.value} 금지")
        if to is S.DESTROYED:
            for i in range(len(self.key)):
                self.key[i] = 0          # 지울 때는 값부터 0으로
        self.state = to

k = Slot("ota-verify-key")
k.move(S.ACTIVE); k.move(S.DEACTIVATED); k.move(S.DESTROYED)
print(k.kid, k.state.value, "남은 값 합:", sum(k.key))
try:
    k.move(S.ACTIVE)
except ValueError as e:
    print(e)
